def seed_100_movies():
    db: Session = SessionLocal()
    try:
        print(f"Total curated movie titles ready: {len(MOVIES_100)}")
        
        # Check existing movies by title
        existing_titles = set(m.title for m in db.query(Movie).all())
        
        added_count = 0
        now = datetime.now()
        
        for t, d, g, l, dur, rat, rel_str, p, tr in MOVIES_100:
            if t not in existing_titles:
                try:
                    rel_dt = datetime.strptime(rel_str, "%Y-%m-%d")
                except ValueError:
                    rel_dt = now - timedelta(days=30)
                
                new_m = Movie(
                    title=t,
                    description=d,
                    genre=g,
                    language=l,
                    duration=dur,
                    rating=rat,
                    release_date=rel_dt,
                    poster_url=p,
                    trailer_url=tr,
                    is_active=True
                )
                db.add(new_m)
                added_count += 1
        
        db.commit()
        print(f"Successfully added {added_count} new movies! Total movies in DB: {db.query(Movie).count()}")
        
        # Now schedule screenings for movies that do not have active upcoming screenings
        screens = db.query(Screen).all()
        if screens:
            all_movies = db.query(Movie).all()
            scheduled_new = 0
            
            # Today, tomorrow, day after
            dates = [
                now.strftime("%Y-%m-%d"),
                (now + timedelta(days=1)).strftime("%Y-%m-%d"),
                (now + timedelta(days=2)).strftime("%Y-%m-%d"),
            ]
            
            times = ["10:30:00", "14:15:00", "18:00:00", "21:45:00"]
            
            for m in all_movies:
                # If movie has 0 screenings, create 2-3 screenings across screens
                existing_scr = db.query(Screening).filter(Screening.movie_id == m.movie_id).count()
                if existing_scr == 0:
                    chosen_screen = random.choice(screens)
                    chosen_date = random.choice(dates)
                    chosen_time = random.choice(times)
                    st = datetime.strptime(f"{chosen_date} {chosen_time}", "%Y-%m-%d %H:%M:%S")
                    et = st + timedelta(minutes=m.duration + 20)
                    
                    scr = Screening(
                        movie_id=m.movie_id,
                        screen_id=chosen_screen.screen_id,
                        start_time=st,
                        end_time=et,
                        status="Scheduled"
                    )
                    db.add(scr)
                    db.flush()
                    
                    # Prices
                    base_p = random.choice([250, 300, 350, 400])
                    db.add(ScreeningPrice(screening_id=scr.screening_id, seat_category="Regular", ticket_price=base_p))
                    db.add(ScreeningPrice(screening_id=scr.screening_id, seat_category="Premium", ticket_price=base_p + 150))
                    db.add(ScreeningPrice(screening_id=scr.screening_id, seat_category="Recliner", ticket_price=base_p + 400))
                    
                    scheduled_new += 1
            
            db.commit()
            print(f"Successfully scheduled {scheduled_new} new screenings for newly added movies!")
            
    except Exception as e:
        db.rollback()
        print(f"Error seeding movies: {e}")
        raise e
    finally:
        db.close()

if __name__ == "__main__":
    seed_100_movies()
